function numIslands(grid) {
  const R = grid.length
  if (R === 0) return 0
  const C = grid[0].length
  const seen = Array.from({ length: R }, () => new Array(C).fill(false))
  let count = 0
  for (let r = 0; r < R; r++) {
    for (let c = 0; c < C; c++) {
      if (grid[r][c] !== 1 || seen[r][c]) continue
      count++
      const stack = [[r, c]]
      seen[r][c] = true
      while (stack.length) {
        const [y, x] = stack.pop()
        for (const [dy, dx] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
          const ny = y + dy
          const nx = x + dx
          if (ny >= 0 && nx >= 0 && ny < R && nx < C && grid[ny][nx] === 1 && !seen[ny][nx]) {
            seen[ny][nx] = true
            stack.push([ny, nx])
          }
        }
      }
    }
  }
  return count
}

