function createUnionFind(n) {
  const parent = Array.from({ length: n }, (_, i) => i)
  const size = new Array(n).fill(1)
  let groups = n
  const find = (x) => {
    while (parent[x] !== x) {
      parent[x] = parent[parent[x]]
      x = parent[x]
    }
    return x
  }
  return {
    find,
    union(a, b) {
      let ra = find(a)
      let rb = find(b)
      if (ra === rb) return false
      if (size[ra] < size[rb]) [ra, rb] = [rb, ra]
      parent[rb] = ra
      size[ra] += size[rb]
      groups--
      return true
    },
    connected(a, b) {
      return find(a) === find(b)
    },
    count() {
      return groups
    },
  }
}

