function dijkstra(n, edges, start) {
  const adj = Array.from({ length: n }, () => [])
  for (const [u, v, w] of edges) adj[u].push([v, w])
  const dist = new Array(n).fill(Infinity)
  dist[start] = 0
  const heap = [[0, start]]
  const swap = (a, b) => {
    ;[heap[a], heap[b]] = [heap[b], heap[a]]
  }
  const push = (item) => {
    heap.push(item)
    let i = heap.length - 1
    while (i > 0) {
      const p = Math.floor((i - 1) / 2)
      if (heap[p][0] <= heap[i][0]) break
      swap(p, i)
      i = p
    }
  }
  const pop = () => {
    const top = heap[0]
    const last = heap.pop()
    if (heap.length > 0) {
      heap[0] = last
      let i = 0
      while (true) {
        let s = i
        const l = 2 * i + 1
        const r = 2 * i + 2
        if (l < heap.length && heap[l][0] < heap[s][0]) s = l
        if (r < heap.length && heap[r][0] < heap[s][0]) s = r
        if (s === i) break
        swap(i, s)
        i = s
      }
    }
    return top
  }
  while (heap.length) {
    const [d, u] = pop()
    if (d > dist[u]) continue
    for (const [v, w] of adj[u]) {
      if (d + w < dist[v]) {
        dist[v] = d + w
        push([dist[v], v])
      }
    }
  }
  return dist
}
